return async function getClient() {
  if (!pending) {
    const attempt = connect();
    pending = attempt;
    attempt.catch(() => {
      if (pending === attempt) pending = null;
    });
  }
  try {
    return await pending;
  } catch (error) {
    throw new Error("Client initialisation failed", { cause: error });
  }
};

